  wire          rx_busy;
  wire          rx_overrun_error;
  wire          rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk              (clk),
    .rst              (rst),
    .s_axis_tdata     (s_axis_tdata),
    .s_axis_tvalid    (s_axis_tvalid),
    .s_axis_tready    (s_axis_tready),
    .m_axis_tdata     (m_axis_tdata),
    .m_axis_tvalid    (m_axis_tvalid),
    .m_axis_tready    (m_axis_tready),
    .rxd              (rxd),
    .txd              (txd),
    .tx_busy          (tx_busy),
    .rx_busy          (rx_busy),
    .rx_overrun_error (rx_overrun_error),
    .rx_frame_error   (rx_frame_error),
    .prescale         (prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b0; wait_clks(2);
    rst = 1'b1; wait_clks(4);
    rst = 1'b0; wait_clks(4);
  endtask

  // Sends an 8N1 UART frame. On the selected data bit, inserts a short
  // opposite-level pulse while the correct bit level is otherwise held.
  task automatic send_glitch_byte(input logic [7:0] b, input int glitch_bit);
    rxd = 1'b0;
    wait_clks(BIT_CLKS);

    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      if (i == glitch_bit) begin
        wait_clks(GLITCH_PRE);
        rxd = ~b[i];
        wait_clks(GLITCH_PULSE);
        rxd = b[i];
        wait_clks(BIT_CLKS - GLITCH_PRE - GLITCH_PULSE);
      end else begin
        wait_clks(BIT_CLKS);
      end
    end

    rxd = 1'b1;
    wait_clks(BIT_CLKS);
  endtask

  initial begin
    do_reset();

    // 0xA5 = 8'b10100101
    // Bit 4 is 0, bit 3 is 0, so the glitch pulse produces exactly two
    // rxd_reg transitions inside the bit_cnt 5 data-bit interval.
    send_glitch_byte(8'hA5, 4);

    // 0x5A = 8'b01011010
    // Bit 2 is 1, bit 1 is 1, so the glitch pulse produces exactly two
    // rxd_reg transitions inside the bit_cnt 7 data-bit interval.
    send_glitch_byte(8'h5A, 2);

    wait_clks(100);
    $finish;
  end

  initial begin
    #10ms;
    $finish;
  end

endmodule
